import{_ as n,c as r,o as d,b0 as k}from"./chunks/framework.Dmsv_Tiv.js";const t="/media-docs/assets/image-20251202203927487.CiypRcO0.png",o="/media-docs/assets/image-20251202203800431.DQ49L6eF.png",p="/media-docs/assets/image-20251202204139915.C7BMXJ0B.png",s="data:image/png;base64,",a="/media-docs/assets/image-20251202204457870.BjNBAhra.png",i="/media-docs/assets/image-20251202204625925.DVwAa6CL.png",l="data:image/png;base64,",J="/media-docs/assets/image-20251202204850021.DOWvk4Ry.png",c="/media-docs/assets/image-20251202205852268.DODYMa4Y.png",h="/media-docs/assets/image-20251202210007380.GZuxd5kl.png",S="/media-docs/assets/image-20251202222159214.CO6R2S2g.png",u="/media-docs/assets/image-20251202222835909.8Qi06_Jx.png",g="/media-docs/assets/image-20251202222951672.C7iHxKxZ.png",m="/media-docs/assets/image-20251202223232240.B9d8cPmu.png",v=JSON.parse('{"title":"LV005-流媒体服务器","description":null,"frontmatter":{"title":"LV005-流媒体服务器","date":"2025-12-02T20:24:56.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/avtools/vlc/126b19b6ab5811d30a5abf67","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-02T20:24:56.285Z","fulluuid":"30a5abf67b684db6972792897a305509","useduuid":"30a5abf67"}},"headers":[],"relativePath":"sdoc/avtools/vlc/126b19b6ab5811d30a5abf67.md","filePath":"sdoc/80-常用工具/10-VLC/LV005-流媒体服务器.md","lastUpdated":1767537778000}'),y={name:"sdoc/avtools/vlc/126b19b6ab5811d30a5abf67.md"};function b(E,e,A,I,Q,L){return d(),r("div",null,[...e[0]||(e[0]=[k('<h1 id="lv005-流媒体服务器" tabindex="-1">LV005-流媒体服务器 <a class="header-anchor" href="#lv005-流媒体服务器" aria-label="Permalink to &quot;LV005-流媒体服务器&quot;">​</a></h1><p>VLC 的功能很强大， 它不仅仅是一个视频播放器， 也可作为小型的视频服务器， 更可以一边播放一边转码， 把视频流发送到网络上。</p><h2 id="一、本地视频文件" tabindex="-1">一、本地视频文件 <a class="header-anchor" href="#一、本地视频文件" aria-label="Permalink to &quot;一、本地视频文件&quot;">​</a></h2><h3 id="_1-rtsp-服务器" tabindex="-1">1. RTSP 服务器 <a class="header-anchor" href="#_1-rtsp-服务器" aria-label="Permalink to &quot;1. RTSP 服务器&quot;">​</a></h3><ul><li>（1）【媒体】→【流】→【文件】→【添加】→【串流】→【流输出面板】→【下一个】</li></ul><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+t+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+o+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+p+'" style="width:100%;height:auto;"></td></tr></tbody></table><ul><li>（2）还是在【流输出面板】→【新目标】→【RTSP】→【添加】→【路径】→【下一个】→【配置文件】→【下一个】</li></ul><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+s+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+a+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+i+'" style="width:100%;height:auto;"></td></tr></tbody></table><p>这里选择 TS 流，它是一个一个的片段，在任意时刻我们可以找到同步头，可以播放出来，这是 TS 流的好处。</p><ul><li>（3）还是【流输出面板】→【流】</li></ul><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+l+'" style="width:80%;height:auto;"></td><td align="center" style="border:none;"><img src="'+J+`" style="width:80%;height:auto;"></td></tr></tbody></table><p>参数说明如下(rtp 是传输协议，rtsp 是控制协议)：</p><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vcodec=h264：H264 编码</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vb=800：视频的比特率</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> acodec=mpga：音频的编码</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ab=128：音频的比特数</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> channels=2：声道数</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> samplerate=44100：采样率</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rtsp://:8554/test1：播放路径</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>然后就能看到进度条在播了，这里这个时间有点短，后面可以把这个下载下来：</p><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://images.videolan.org/images/vlc-player.mp4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>需要注意，这里并不是作为播放器，而是作为服务器把视频流发送到网络上，所以这里是看不到画面的。</p><h3 id="_2-播放器" tabindex="-1">2. 播放器 <a class="header-anchor" href="#_2-播放器" aria-label="Permalink to &quot;2. 播放器&quot;">​</a></h3><p>然后我们再打开一个VLC，然后【媒体】→【打开网络串流】→【网络】→【网络协议中输入URL】，这里的URL为<code>rtsp://:8554/test1</code></p><table><tbody><tr style="border:none;"><td align="center" style="border:none;">打开网络串流<br> <img src="`+c+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;">左侧为RTSP服务器,右侧为播放器<br> <img src="'+h+'" style="width:100%;height:auto;"></td></tr></tbody></table><p>左边是 VLC 作为流媒体服务器，作为推流，右边是 VLC 播放器打开网络串流，是一个小型的播放器</p><blockquote><p>可以打开多个播放器打开网络串流。</p></blockquote><h2 id="二、采集摄像头数据" tabindex="-1">二、采集摄像头数据 <a class="header-anchor" href="#二、采集摄像头数据" aria-label="Permalink to &quot;二、采集摄像头数据&quot;">​</a></h2><blockquote><p>电脑要先有一个摄像头，像我的笔记本，就自带了一个。其实这里可以直接打开摄像头捕获摄像头画面的，但是我们这里是搭建流媒体服务器，就用一个 VLC 推流，用另一个拉流。</p></blockquote><h3 id="_1-rtsp-服务器-1" tabindex="-1">1. RTSP 服务器 <a class="header-anchor" href="#_1-rtsp-服务器-1" aria-label="Permalink to &quot;1. RTSP 服务器&quot;">​</a></h3><ul><li>（1）【媒体】→【流】→【捕获设备】→【视频名称】→【Integrated Camera】→【串流】→【流输出面板】→【下一个】</li></ul><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+t+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+S+'" style="width:75%;height:auto;"></td><td align="center" style="border:none;"><img src="'+u+'" style="width:80%;height:auto;"></td></tr></tbody></table><ul><li>（2）【流输出面板】→【新目标】→【RTSP】→【添加】→【修改路径】→【点击下一个】→【选择TS流】→【下一个】</li></ul><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+s+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+a+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+i+'" style="width:100%;height:auto;"></td></tr></tbody></table><ul><li>（3）【流输出面板】→【选择流】</li></ul><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+l+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+g+'" style="width:78%;height:auto;"></td></tr></tbody></table><p>点击完流就可以看到 VLC 的进度条开始动了，这个就表示 RTSP 流媒体服务器搭建好了，现在正在推流。</p><h3 id="_2-客户端拉流" tabindex="-1">2. 客户端拉流 <a class="header-anchor" href="#_2-客户端拉流" aria-label="Permalink to &quot;2. 客户端拉流&quot;">​</a></h3><p>再打开一个 VLC media player，选择【媒体】→【打开网络串流】→【网络 URL 修改为：rtsp://: 8554/test1】→【点击播放】：</p><p><img src="'+m+'" alt="image-20251202223232240"></p><p>说明：我是放了个橙子的，看起来颜色不是很对，而且旋转了 180 度，不过下面有个扩展配置，里面可以做旋转还有一些其他效果，反正是测试效果，先这样看。</p><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/qq_41839588/article/details/132632031?spm=1001.2014.3001.5501" target="_blank" rel="noreferrer">音视频开发常用工具_mediainfo-CSDN 博客</a></p><p><a href="https://blog.csdn.net/qq_41839588/article/details/133220159" target="_blank" rel="noreferrer">RTSP 协议抓包及讲解_rtsp 流怎么获取-CSDN 博客</a></p></blockquote>',36)])])}const T=n(y,[["render",b]]);export{v as __pageData,T as default};
